customCSS:
/* Ohlala custom slides */
.slide.tall { height: auto; min-height: 100vh; padding: 80px 0; }
.ohl-statrow { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; width: 100%; }
.ohl-stat { position: relative; border-radius: var(--radius-card); padding: 12px; background: var(--bg-card-glass); backdrop-filter: blur(4.5px); -webkit-backdrop-filter: blur(4.5px); overflow: hidden; }
.ohl-stat::before { content:''; position:absolute; inset:0; border-radius: var(--radius-card); padding:1px; background: linear-gradient(157deg, rgba(255,255,255,0.20) 2.12%, rgba(255,255,255,0) 39%, rgba(255,255,255,0) 54.33%, rgba(255,255,255,0.08) 93.02%); -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); mask-composite: exclude; pointer-events:none; }
.ohl-stat::after { content:''; position:absolute; inset:0; border-radius: var(--radius-card); box-shadow: inset 0 0 14px 0 rgba(111,111,129,0.25); pointer-events:none; }
.ohl-stat-inner { position: relative; display: flex; align-items: center; gap: 20px; background: linear-gradient(to top, rgba(6,6,6,0.6) 0%, rgba(17,17,19,0.3) 83.56%, rgba(27,27,30,0.2) 110%); border-radius: var(--radius-inner); padding: 24px 26px; }
.ohl-stat-ico { flex-shrink:0; width: 52px; height: 52px; border-radius: 50%; display:flex; align-items:center; justify-content:center; background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.16), rgba(255,255,255,0.02)); box-shadow: inset 0 1px 1px rgba(255,255,255,0.25), inset 0 -2px 3px rgba(0,0,0,0.4); }
.ohl-stat-ico img { width: 26px; height: 26px; filter: brightness(0) invert(1) opacity(0.82); }
.ohl-stat-txt { display:flex; flex-direction:column; gap:4px; min-width:0; }
.ohl-stat-val { font-size: 34px; font-weight: 700; color:#fff; line-height:1; }
.ohl-stat-lbl { font-size: 12px; font-weight: 500; color: rgba(255,255,255,0.84); text-transform: uppercase; letter-spacing: 0.04em; }
.ohl-stat4 { display:grid; grid-template-columns: repeat(4,1fr); gap: 14px; width:100%; }
.ohl-statc { position:relative; border-radius: var(--radius-inner); padding: 24px 18px; background: rgba(20,20,22,0.6); display:flex; flex-direction:column; align-items:center; gap:14px; text-align:center; overflow:hidden; }
.ohl-statc::before { content:''; position:absolute; inset:0; border-radius: var(--radius-inner); padding:1px; background: linear-gradient(180deg, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0) 100%); -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); mask-composite: exclude; pointer-events:none; }
.ohl-statc .ico { width: 46px; height: 46px; border-radius: 50%; display:flex; align-items:center; justify-content:center; background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.14), rgba(255,255,255,0.02)); box-shadow: inset 0 1px 1px rgba(255,255,255,0.22), inset 0 -2px 3px rgba(0,0,0,0.4); }
.ohl-statc .ico img { width: 24px; height:24px; filter: brightness(0) invert(1) opacity(0.8); }
.ohl-statc .val { font-size: 36px; font-weight:700; color:#efefef; line-height:1; }
.ohl-statc .val sup { font-size: 20px; font-weight:600; }
.ohl-statc .lbl { font-size: 11px; font-weight:500; color:#a3a3ae; text-transform:uppercase; letter-spacing:0.07em; line-height:1.3; }
.ohl-items { display:flex; flex-direction:column; gap:16px; width:100%; }
.ohl-item { position:relative; border-radius: var(--radius-card); padding: 22px 24px; display:flex; gap:24px; align-items:flex-start; background: linear-gradient(180deg, rgba(65,36,28,0.09) 11.28%, rgba(13,12,14,0.4) 128.43%); }
.ohl-item::before { content:''; position:absolute; inset:0; border-radius:inherit; padding:1px; background: linear-gradient(180deg, rgba(255,255,255,0.24) 0%, rgba(255,255,255,0) 100%); -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); mask-composite: exclude; pointer-events:none; }
.ohl-item .num { flex-shrink:0; width:56px; height:56px; display:flex; align-items:center; justify-content:center; border-radius:12px; background: rgba(86,79,77,0.24); box-shadow: inset 1px 2px 2px rgba(255,255,255,0.67), inset 0 -3px 2px rgba(0,0,0,0.23), inset -2px -2px 2px rgba(229,229,229,0.25); }
.ohl-item .num span { background-image: linear-gradient(155.68deg, rgba(255,255,255,0.65) 32.68%, rgba(255,255,255,0) 98.12%); -webkit-background-clip:text; background-clip:text; color:transparent; font-size:27px; font-weight:700; }
.ohl-item h3 { font-size: 21px; font-weight:700; color:#c7c7cc; line-height:normal; }
.ohl-item p { font-size: 15px; color:#a3a3ae; line-height:1.5; margin-top:8px; }
.ohl-frame { position:relative; border-radius: 24px; padding: 8px; overflow:hidden; box-shadow: 0 0 64px 0 rgba(217,228,231,0.12); }
.ohl-frame::before { content:''; position:absolute; inset:0; border-radius:24px; padding:1px; background: linear-gradient(180deg, rgba(207,207,207,0.55) 0%, rgba(105,105,105,0.28) 50%, rgba(105,105,105,0.40) 100%); -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); mask-composite: exclude; pointer-events:none; z-index:1; }
.ohl-frame img { display:block; width:100%; height:100%; object-fit:cover; border-radius:inherit; }
/* device mockups: image IS already a device (bezel + dark bg baked-in) -> no silver frame, no clip, just soft shadow */
.ohl-device { position:relative; padding:0; border-radius:0; overflow:visible; filter: drop-shadow(0 24px 60px rgba(0,0,0,0.55)) drop-shadow(0 0 60px rgba(217,228,231,0.10)); }
.ohl-device img { display:block; width:100%; height:auto; object-fit:contain; border-radius:0; }
.ohl-tab { display:inline-flex; align-items:center; justify-content:center; background:#141415; border-radius:40px; padding:8px 18px; font-size:13px; font-weight:500; color:#e5e5e5; position:relative; white-space:nowrap; }
.ohl-tab::before { content:''; position:absolute; inset:0; border-radius:40px; padding:1px; background: linear-gradient(157deg, rgba(255,255,255,0.40) 2.12%, rgba(255,255,255,0) 39%, rgba(255,255,255,0) 54.33%, rgba(255,255,255,0.10) 93.02%); -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); mask-composite: exclude; pointer-events:none; }
.ohl-note { position:relative; border-radius: var(--radius-card); padding: 28px; background: rgba(28,28,30,0.43); box-shadow: 0 0 44px 0 rgba(76,131,83,0.03), 0 0 64px 0 rgba(217,228,231,0.16); }
.ohl-note::after { content:''; position:absolute; inset:0; border-radius:inherit; box-shadow: inset -1px -1px 14px 0 rgba(255,255,255,0.07), inset 1px 1px 3px 0 rgba(255,255,255,0.12); pointer-events:none; }
.ohl-note h3 { position:relative; font-size:21px; font-weight:700; color:#efefef; margin-bottom:14px; }
.ohl-note p { position:relative; font-size:16px; color:#a3a3ae; line-height:1.55; }
@media (max-width: 860px) {
  .ohl-statrow, .ohl-stat4 { grid-template-columns: 1fr 1fr; }
  .ohl-2col { grid-template-columns: 1fr !important; }
}
@media (max-width: 560px) {
  .ohl-statrow, .ohl-stat4 { grid-template-columns: 1fr; }
  .ohl-stat-val { font-size: 28px; }
  .ohl-statc .val { font-size: 30px; }
}
.ohl-iphone { position:relative; background:#0a0a0a; border-radius:46px; padding:11px; box-shadow:0 24px 60px rgba(0,0,0,0.55), 0 0 60px rgba(217,228,231,0.10); }
.ohl-iphone::after { content:''; position:absolute; top:11px; left:50%; transform:translateX(-50%); width:38%; height:26px; background:#0a0a0a; border-radius:0 0 18px 18px; z-index:2; pointer-events:none; }
.ohl-iphone .ohl-screen { position:relative; border-radius:36px; overflow:hidden; width:100%; height:100%; }
.ohl-iphone .ohl-screen img { display:block; width:100%; height:100%; object-fit:cover; object-position:top center; }

.ohl-fade { position:relative; width:100%; }
.ohl-fade img { display:block; width:100%; height:auto; -webkit-mask-image: linear-gradient(to bottom, transparent 0%, #000 5%, #000 95%, transparent 100%); mask-image: linear-gradient(to bottom, transparent 0%, #000 5%, #000 95%, transparent 100%); }
/* cutout détouré (fond transparent) : sujet ENTIER sur fond noir, AUCUN masque ni crop */
.ohl-cutout { position:relative; width:100%; display:flex; justify-content:center; transition: transform 0.45s cubic-bezier(0.22,1,0.36,1); }
.ohl-cutout img { display:block; width:100%; height:auto; object-fit:contain; filter: drop-shadow(0 28px 56px rgba(0,0,0,0.45)); }
.ohl-cutout:hover { transform: translateY(-6px); }
@media (prefers-reduced-motion: reduce){ .ohl-cutout { transition:none !important; transform:none !important; } }

/* ── Animations premium subtiles (scopé ohlala) ── */
/* Hover lift doux sur cards / items / devices */
.ohl-note, .ohl-stat, .ohl-statc, .ohl-item, .ohl-iphone, .ohl-fade, .ohl-frame, .ohl-tablet { transition: transform 0.45s cubic-bezier(0.22,1,0.36,1), box-shadow 0.45s cubic-bezier(0.22,1,0.36,1); }
.ohl-note:hover, .ohl-stat:hover, .ohl-statc:hover, .ohl-item:hover { transform: translateY(-6px); }
.ohl-iphone:hover, .ohl-fade:hover, .ohl-frame:hover { transform: translateY(-8px) scale(1.012); }
/* Stagger : les enfants .fade-up d'un même groupe apparaissent en cascade */
.ohl-statrow .ohl-stat, .ohl-stat4 .ohl-statc, .ohl-items .ohl-item { opacity:0; transform:translateY(24px); transition: opacity 0.7s cubic-bezier(0.22,1,0.36,1), transform 0.7s cubic-bezier(0.22,1,0.36,1); }
.visible .ohl-statrow .ohl-stat, .visible .ohl-stat4 .ohl-statc, .visible .ohl-items .ohl-item,
.ohl-statrow.visible .ohl-stat, .ohl-stat4.visible .ohl-statc, .ohl-items.visible .ohl-item { opacity:1; transform:translateY(0); }
.ohl-statrow .ohl-stat:nth-child(1), .ohl-stat4 .ohl-statc:nth-child(1), .ohl-items .ohl-item:nth-child(1){ transition-delay:0.05s; }
.ohl-statrow .ohl-stat:nth-child(2), .ohl-stat4 .ohl-statc:nth-child(2), .ohl-items .ohl-item:nth-child(2){ transition-delay:0.15s; }
.ohl-statrow .ohl-stat:nth-child(3), .ohl-stat4 .ohl-statc:nth-child(3), .ohl-items .ohl-item:nth-child(3){ transition-delay:0.25s; }
.ohl-stat4 .ohl-statc:nth-child(4), .ohl-items .ohl-item:nth-child(4){ transition-delay:0.35s; }
/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce){ .ohl-note,.ohl-stat,.ohl-statc,.ohl-item,.ohl-iphone,.ohl-fade,.ohl-frame{ transition:none !important; transform:none !important; } }

/* ── Parallax hero uniquement (image cover, marge sûre) — pas sur les images entières ── */
@supports (animation-timeline: view()) {
  @keyframes ohl-hero-rise { from { transform: scale(1.08) translateY(-2%); } to { transform: scale(1.08) translateY(2%); } }
  #slide-0 > img { animation: ohl-hero-rise linear; animation-timeline: view(); animation-range: entry 0% exit 100%; will-change: transform; }
}
@media (prefers-reduced-motion: reduce){
  @supports (animation-timeline: view()){ #slide-0 > img { animation: none !important; } }
}

/* tablette device : cadre bezel gris arrondi, screenshot cropé en haut (hero) */
.ohl-tablet { position:relative; background:#1c1c1e; border-radius:28px; padding:10px; box-shadow:0 24px 60px rgba(0,0,0,0.55), 0 0 60px rgba(217,228,231,0.10); }
.ohl-tablet::before { content:''; position:absolute; inset:0; border-radius:28px; padding:1px; background:linear-gradient(160deg, rgba(255,255,255,0.35) 0%, rgba(255,255,255,0.05) 40%, rgba(255,255,255,0.12) 100%); -webkit-mask:linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite:xor; mask:linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); mask-composite:exclude; pointer-events:none; z-index:2; }
.ohl-tablet .ohl-screen { position:relative; border-radius:19px; overflow:hidden; width:100%; }
.ohl-tablet .ohl-screen img { display:block; width:100%; height:100%; object-fit:cover; object-position:top center; }
.ohl-tablet:hover { transform:translateY(-8px) scale(1.012); }
@media (prefers-reduced-motion: reduce){ .ohl-tablet { transition:none !important; transform:none !important; } }
/* icônes Figma natives (relief + couleur) : pas de filtre monochrome */
.ohl-stat-ico.ohl-ico-native img { filter:none !important; width:30px; height:30px; }

/* ===== RESPONSIVE mobile + tablette (ajouté 2026-06-25) ===== */
.slide { overflow-x: hidden; }
@media (max-width: 1024px) {
  .ohl-2col { grid-template-columns: 1fr !important; max-width: 560px !important; }
}
@media (max-width: 768px) {
  .slide { padding: 56px 20px !important; }
  .slide.tall { padding: 64px 20px !important; }
  .slide-content { gap: 32px !important; }
  .ohl-2col { gap: 36px !important; row-gap: 36px !important; }
  .ohl-items { gap: 22px !important; }
  .ohl-statrow { gap: 18px !important; }
  .ohl-phones { flex-direction: column !important; gap: 44px !important; align-items: center !important; }
  .ohl-phones .ohl-iphone { width: min(260px, 78vw) !important; }
  .ohl-tablet, .ohl-device, .ohl-frame, .ohl-fade, .ohl-cutout { max-width: 100% !important; }
  .ohl-note { padding: 22px !important; }
  .ohl-note-hero { padding: 24px 22px !important; }
  .ohl-note-hero h2 { font-size: 25px !important; }
  .ohl-item { flex-direction: column !important; gap: 14px !important; padding: 18px 18px !important; }
}
@media (max-width: 560px) {
  .ohl-phones .ohl-iphone { width: min(240px, 82vw) !important; }
  .ohl-tab { font-size: 12px !important; padding: 6px 12px !important; }
}
